export type Category = 'Pens' | 'Stickers' | 'Car Freshies' | 'Canvas' | 'Custom'

/** Custom cart-line meta (logo stickers, banners, canvas, business cards, freshie scent). */
export type CustomLineType = 'logo' | 'banner' | 'canvas' | 'business-cards' | 'thank-you-cards' | 'photo-freshie'

export interface CustomLogoMeta {
  /** Discriminator for custom configurator lines */
  type?: CustomLineType
  /** Logo sticker style — required on custom logo lines */
  style?: 'vinyl' | 'holo' | 'glow'
  styleLabel?: string
  /** Cut / shape choice (same price as selected style) */
  cut?: 'circle' | 'rounded' | 'diecut'
  cutLabel?: string
  stickerQty?: number
  /** Selected sticker size label, e.g. 3" */
  stickerSize?: string
  /** Size id: '2' | '3' | '4' | '5' */
  stickerSizeId?: string
  logoDataUrl?: string
  fileName?: string
  /** Admin-protected artwork path, e.g. /api/admin/uploads/custom/<uuid>.jpg */
  artworkUrl?: string
  /** Stored filename / upload id */
  artworkId?: string
  /** Original customer filename for downloads */
  artworkFileName?: string
  logoComingByEmail?: boolean
  /** Car Freshie scent selection */
  freshieScent?: string
  /** Optional color / note request for freshies */
  freshieNote?: string
  /** Round custom photo freshie */
  photoFreshieSize?: string
  /** Permanent paid-order archive path, populated by the server. */
  archivedArtworkPath?: string
  /** Banner configurator */
  bannerSizeId?: string
  bannerSizeLabel?: string
  bannerWidthFt?: number
  bannerHeightFt?: number
  bannerSides?: 'single' | 'double'
  bannerNotes?: string
  /** Canvas configurator */
  canvasSizeId?: string
  canvasSizeLabel?: string
  canvasFinish?: 'stretched' | 'framed'
  canvasNotes?: string
  /** Business / thank-you cards configurator pack qty */
  cardPackQty?: number
  cardNotes?: string
  /** Transparent estimate pricing (not an official quote) */
  estimateOnly?: boolean
  /** Generic catalog listing choices, such as Size or Color. */
  selectedOptions?: Record<string, string>
  /** Original live catalog id when a cart row has a variant-specific id. */
  catalogId?: string
}

export interface ProductOptionValue {
  label: string
  priceAdjustment: number
}

export interface ProductOptionGroup {
  name: string
  required: boolean
  values: ProductOptionValue[]
}

export interface Product {
  id: string
  name: string
  category: Category
  price: number
  tagline: string
  description: string
  accent: string
  badge?: string
  art: 'pen' | 'sticker' | 'freshie' | 'resin' | 'badge' | 'pack' | 'skin'
  imageUrl?: string
  /** Missing means made to order; zero means sold out. */
  inventoryQuantity?: number
  optionGroups?: ProductOptionGroup[]
  /** Present on synthetic custom logo sticker cart lines */
  custom?: CustomLogoMeta
}

export const categories = ['All', 'Pens', 'Stickers', 'Car Freshies', 'Canvas', 'Custom'] as const
export type FilterCategory = (typeof categories)[number]

